(()=>{const t=document.querySelector(".search input"),n=[...document.querySelectorAll(".pcard")],a=document.querySelector(".none");if(!t||!n.length)return;const o=e=>e.replace(/ي/g,"ی").replace(/ك/g,"ک").replace(/‌/g," ").replace(/\s+/g," ").trim().toLowerCase();n.forEach(e=>{e.dataset.q=o(e.querySelector("h2").textContent)});const c=()=>{const e=o(t.value);let r=0;n.forEach(s=>{const l=!e||s.dataset.q.includes(e);s.hidden=!l,l&&r++}),a.classList.toggle("is-hidden",r>0)};t.addEventListener("input",c),c()})();
